// pages/Profile.jsx

import React, { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../context/AuthContext';
// 🚨 에러 수정: fetchMyCoupons -> getMyCoupons 로 변경
import { getMyCoupons } from '../api/couponApi'; 
import { fetchReviews } from '../api/reviewApi';
import ReviewCard from '../components/ReviewCard';
import { useNavigate } from 'react-router-dom';

function Profile() {
  const { user } = useContext(AuthContext);
  const [myReviews, setMyReviews] = useState([]);
  const [coupons, setCoupons] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const load = async () => {
      try {
        if (!user) return;
        
        // 💡 서버 측 필터링 권장: 
        // fetchReviews({ page: 1, limit: 20, userId: user.id }); 와 같이
        // 특정 유저의 리뷰만 서버에서 가져오도록 API를 개선하는 것이 좋습니다.
        const reviewRes = await fetchReviews({ page: 1, limit: 20 });
        
        // 현재는 클라이언트에서 필터링 (서버 API가 유저 필터를 지원하지 않을 때의 임시 방편)
        setMyReviews(reviewRes.data.filter(r => r.author && String(r.author._id) === String(user.id)));

        // 🚨 함수 이름 수정: fetchMyCoupons -> getMyCoupons
        const cRes = await getMyCoupons(); 
        setCoupons(cRes.data || []); // 서버 응답 구조에 따라 cRes.data 또는 cRes로 수정 가능
      } catch (err) {
        console.error(err);
      }
    };
    load();
    
    // user가 변경될 때마다 로드
  }, [user]); 

  return (
    <div style={{ padding: 20 }}>
      <h1>👤 {user ? user.username : '프로필'}</h1>
      <div style={{ marginTop: 12 }}>
        <h3>내가 작성한 리뷰</h3>
        {myReviews.length === 0 ? (
          <p style={{ color: '#999' }}>아직 작성한 리뷰가 없습니다.</p>
        ) : (
          myReviews.map(r => <ReviewCard 
            key={r._id} 
            id={r._id} 
            username={r.author?.username} 
            title={r.title} 
            text={r.text} 
            images={r.images} 
            createdAt={r.createdAt} 
            likes={r.likes} 
          />)
        )}
      </div>

      <div style={{ marginTop: 20 }}>
        <h3>내 쿠폰</h3>
        {coupons.length === 0 ? (
          <p style={{ color: '#999' }}>쿠폰이 없습니다.</p>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: 12 }}>
            {coupons.slice(0, 3).map(c => ( // 💡 프로필에서는 3개만 미리보기로 보여주는 것이 좋습니다.
              <div key={c._id} style={{ padding: 12, borderRadius: 8, background: '#fff', boxShadow: '0 6px 16px rgba(0,0,0,0.04)' }}>
                <div style={{ fontSize: 14, fontWeight: 700 }}>{c.brand}</div>
                <div style={{ marginTop: 6 }}>코드: <strong>{c.code}</strong></div>
                <div style={{ marginTop: 6 }}>{c.discount}%</div>
                <button onClick={() => navigate('/couponcenter')} style={{ marginTop: 10, padding: '8px 10px', borderRadius: 8, background: '#0070f3', color: '#fff', border: 'none' }}>쿠폰센터로 이동</button>
              </div>
            ))}
            {coupons.length > 3 && (
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <button onClick={() => navigate('/couponcenter')} style={{ background: 'none', border: '1px solid #0070f3', color: '#0070f3', padding: '10px 15px', borderRadius: 8, cursor: 'pointer' }}>
                        + {coupons.length - 3}개 더 보기
                    </button>
                </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default Profile;
